fn solve(a: i8) -> i8 {
    // Convert i8 to u8 for easier manipulation since we know a is nonnegative
    let mut v = a as u8;
    let mut count = 0;

    while v > 0 {
        // Check if the least significant octal digit is 1
        if v % 8 == 1 {
            count += 1;
        }
        // Move to the next digit in octal representation
        v /= 8;
    }

    count as i8 // Convert back to i8 before returning
}